    "id": "log-208-glossaire-reconstitue",
    "kind": "glossaire",
    "blocks": [
      {
        "kind": "paragraph",
        "text": "{g}acceptation{/g} — Accord donné à une proposition, dans les conditions applicables."
      },
      {
        "kind": "paragraph",
        "text": "{g}bon de commande{/g} — Document qui précise les articles, les quantités, le prix et les conditions de commande."
      },
      {
        "kind": "paragraph",
        "text": "{g}CGV{/g} — Conditions générales de vente applicables lorsqu’elles sont valablement intégrées à l’accord."
      },
      {
        "kind": "paragraph",
        "text": "{g}conseil de vente{/g} — Information qui aide le client à choisir une offre adaptée à un besoin."
      },
      {
        "kind": "paragraph",
        "text": "{g}contrat de vente{/g} — Accord par lequel le vendeur s’engage à remettre le bien et l’acheteur à payer le prix."
      },
      {
        "kind": "paragraph",
        "text": "{g}fidélité{/g} — Choix répété d’un client de s’adresser au même fournisseur."
      },
      {
        "kind": "paragraph",
        "text": "{g}offre{/g} — Proposition précisant l’objet, le prix et les conditions de la vente."
      },
      {
        "kind": "paragraph",
        "text": "{g}promotion{/g} — Action limitée ou ciblée visant à faire connaître une offre ou à stimuler ses ventes."
      },
      {
        "kind": "paragraph",
        "text": "{g}réserve de stock{/g} — Quantité temporairement affectée à une commande selon une règle du dépôt."
      },
      {
        "kind": "paragraph",
        "text": "{g}remise{/g} — Réduction d’un prix selon des conditions définies."
      },
      {
        "kind": "paragraph",
        "text": "{g}retrait{/g} — Remise de la commande au client ou à son représentant dans un lieu convenu."
      },
      {
        "kind": "paragraph",
        "text": "{g}télévente{/g} — Entretien ou transaction commerciale par téléphone ou autre canal à distance."
      },
      {
        "kind": "paragraph",
        "text": "{g}vente additionnelle{/g} — Proposition d’un article ou service complémentaire adapté à l’achat principal."
      },
      {
        "kind": "paragraph",
        "text": "{g}vente conseillée{/g} — Vente dans laquelle le client reçoit une aide pour choisir une offre et comprendre son usage."
      }
    ],
